def bs(a, t):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < t:
            lo = mid
        else:
            hi = mid
    return lo

def remove_negatives(numbers: list[int]) -> list[int]:
    for num in numbers:
        if num < 0:
            numbers.remove(num)
    return numbers

class Account:
    def __init__(self):
        self._balance = 0

    @property
    def balance(self):
        return self._balance

a = Account()
a.balance = 50
print(a.balance)

explanation:
@property makes a method readable like an attribute, so a.balance calls it without parentheses. A property with only a getter is read-only, so assigning to it raises AttributeError instead of changing anything. Add a setter when you want writes, for example to validate the value.

@property
def balance(self):         # read:  a.balance
    return self._balance

@balance.setter
def balance(self, value):  # write: a.balance = 50
    if value < 0:
        raise ValueError('balance cannot be negative')
    self._balance = value

