        return "A"

class B(A):
    def hi(self):
        return "B" + super().hi()

class C(A):
    def hi(self):
        return "C" + super().hi()

class D(B, C):
    pass

print(D().hi())

explanation:
__init__() runs automatically when a new object is created, and sets its starting attributes. It never runs on deletion; that is __del__.

class Dog:
    def __init__(self, name):
        self.name = name     # sets the new object's starting state

d = Dog('Rex')               # => __init__ runs here, called for you by Dog(...)
d.name                       # => 'Rex'  (set by __init__)
